# One WebAuthn challenge per ceremony, kept in the session (generated by
# maquina:passkeys).
#
# The browser signs the challenge, so a stored one that could be used twice
# would let a captured response be replayed. take_passkey_challenge removes it
# before anything is verified, and a challenge older than CHALLENGE_TTL is
# refused. Registration and sign-in keep theirs under separate keys, so one
# ceremony never consumes the other's.
module PasskeyChallenge
  extend ActiveSupport::Concern

  CHALLENGE_TTL = 5.minutes

  private

  def store_passkey_challenge(purpose, challenge)
    session[passkey_challenge_key(purpose)] = {
      "challenge" => challenge,
      "expires_at" => CHALLENGE_TTL.from_now.to_i
    }
  end

  def take_passkey_challenge(purpose)
    stored = session.delete(passkey_challenge_key(purpose))
    stored["challenge"] if stored && stored["expires_at"].to_i > Time.current.to_i
  end

  def passkey_challenge_key(purpose)
    :"passkey_#{purpose}_challenge"
  end

  # The browser's PublicKeyCredential#toJSON(). It is checked by signature, not
  # assigned to a record, so only the shape is permitted here.
  def passkey_credential_params
    params.require(:credential).permit(
      :id, :rawId, :type, :authenticatorAttachment,
      response: [:clientDataJSON, :attestationObject, :authenticatorData, :signature, :userHandle,
        :publicKey, :publicKeyAlgorithm, transports: []],
      clientExtensionResults: {}
    ).to_h
  end
end
